                    if not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

        return region

    def is_rectangular(region):
        """Check if region cells form a perfect rectangle"""
        if not region:
            return False
        min_r, max_r = min(r for r, c in region), max(r for r, c in region)
        min_c, max_c = min(c for r, c in region), max(c for r, c in region)
        return len(region) == (max_r - min_r + 1) * (max_c - min_c + 1)

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] > 0:
                region = find_region(r, c)

                if is_rectangular(region):
                    min_r, max_r = min(ro for ro, _ in region), max(ro for ro, _ in region)
                    min_c, max_c = min(co for _, co in region), max(co for _, co in region)

                    # For rectangular regions, inner cells become 8
                    # Border cells keep original color
